@startuml

enum BookingStatus {
  PRELIMINARY
  FINALIZED
  CONFIRMED
  CANCELLED
}

enum PaymentType {
  PRE_PAID
  PAID_AT_HOTEL
}

class HBMS {
}

class Traveller {
  + name : string
  + billingInformation : string
  + reliabilityRating : float
}

class TravelPreference {
  + preference : string
}

class SearchCriteria {
  + city : string
  + arrivalDate : date
  + departureDate : date
  + numberOfRooms : int
  + roomType : string
  + minimumHotelRating : int
  + tentativeBudget : float
}

class Hotel {
  + address : string
  + city : string
}

class HotelChain {
}

class SpecialOffer {
  + price : float
}

class Booking {
  + bookingId : int
  + cancellationDeadline : date
  + status : BookingStatus
  + paymentType : PaymentType
  + creditCardInformation : string
}

class BookingInfo {
  + price : float
  + cityArea : string
  + hotelRating : int
}

Traveller "1" -- "*" TravelPreference
Traveller "1" -- "*" Booking
Traveller "1" -- "*" SearchCriteria
HBMS "1" -- "*" Traveller
HBMS "1" -- "*" Hotel
HBMS "1" -- "*" Booking
HBMS "1" -- "*" SpecialOffer
HBMS "1" -- "*" BookingInfo

HotelChain "0..1" -- "*" Hotel
Hotel "1" -- "*" Booking
Hotel "1" -- "*" SpecialOffer
Hotel "1" -- "*" BookingInfo

Booking "1" -- "1" BookingInfo
Booking "1" -- "0..5" SpecialOffer

@enduml

